def add_overlap_constraints(apps, schema_editor):
    """PostgreSQL only: the database itself refuses overlapping live holds.

    * one stylist cannot have two live holds whose time ranges overlap;
    * one customer cannot hold two overlapping times.
    "Live" = status active or confirmed. Needs the btree_gist extension (equality on ids next to
    a range overlap). Other databases (the SQLite used by quick local checks) skip this and rely
    on the application checks only; production is PostgreSQL.
    """
